import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, it } from 'node:test';

/**
 * Bug bounty #43 (forged notification reply) and #44 (forced call answer through the
 * exported MainActivity). The Android classes are generated by config plugins, so the
 * boundaries are covered at the source level, like the other native policy tests.
 */
const read = (relative: string): string => readFileSync(resolve(process.cwd(), relative), 'utf8');

const CALL_PLUGIN = read('plugins/withNativeIncomingCallAndroid.cjs');
const NOTIFEE_PLUGIN = read('plugins/withNotifeeReceiverHardeningAndroid.cjs');
const APP_CONFIG = read('app.config.js');
const TRAY_EVENTS = read('src/notifications/events/trayEvents.ts');

const guardSource = (): string => {
  const start = CALL_PLUGIN.indexOf('object CallLaunchGuard {');
  assert.ok(start >= 0, 'CallLaunchGuard must be generated');
  return CALL_PLUGIN.slice(start, CALL_PLUGIN.indexOf('\n}\n', start));
};

describe('Android call launch guard (bug bounty #44)', () => {
  it('strips call extras from MainActivity launches that lack the per-install proof', () => {
    assert.match(CALL_PLUGIN, /CallLaunchGuard\.sanitize\(this, intent\)/);
    assert.match(CALL_PLUGIN, /Could not install CallLaunchGuard in MainActivity/);
    const guard = guardSource();
    assert.match(guard, /SecureRandom\(\)\.nextBytes/);
    assert.match(guard, /MessageDigest\.isEqual/);
    assert.match(guard, /CALL_EXTRAS\.forEach\(intent::removeExtra\)/);
  });

  it('only treats real call actions as call launches, so plain notification taps keep their target', () => {
    const guard = guardSource();
    const triggers = /CALL_TRIGGER_EXTRAS = listOf\(([\s\S]*?)\)/.exec(guard)?.[1] ?? '';
    for (const key of [
      'callAction',
      'isIncomingCall',
      'autoJoinCall',
      'autoDeclineCall',
      'answeredFromLockedScreen',
    ]) {
      assert.match(triggers, new RegExp(`"${key}"`));
    }
    // A chat notification tap carries these; they alone must never trigger stripping.
    assert.doesNotMatch(triggers, /"channelId"|"actionUrl"|"callId"/);
    assert.match(guard, /CALL_TRIGGER_EXTRAS\.any \{ extras\.containsKey\(it\) \}/);
  });

  it('stamps every MainActivity launch the app builds with call actions', () => {
    const launchBlocks = CALL_PLUGIN.split('getLaunchIntentForPackage(').slice(1);
    const callLaunches = launchBlocks
      .map(block => block.slice(0, block.indexOf('\n      }')))
      .filter(block => /putExtra\("(callAction|isIncomingCall|autoJoinCall)"/.test(block));
    assert.ok(callLaunches.length >= 3, 'expected the answer, decline and notification launches');
    for (const block of callLaunches) {
      assert.match(block, /CallLaunchGuard\.stamp\(/);
    }
  });
});

describe('Notifee reply hardening (bug bounty #43)', () => {
  it('stops other apps from starting the Notifee receiver activity', () => {
    assert.match(APP_CONFIG, /withNotifeeReceiverHardeningAndroid\.cjs/);
    assert.match(NOTIFEE_PLUGIN, /app\.notifee\.core\.NotificationReceiverActivity/);
    assert.match(NOTIFEE_PLUGIN, /\$\['android:exported'\] = 'false'/);
    assert.match(NOTIFEE_PLUGIN, /replaced\.add\('android:exported'\)/);
  });

  it('acts on Android Reply / Mark as read only for a notification the app is displaying', () => {
    assert.match(TRAY_EVENTS, /notifee\.getDisplayedNotifications\(\)/);
    assert.match(TRAY_EVENTS, /message\.storeKey !== claimed\.storeKey/);
    assert.match(
      TRAY_EVENTS,
      /Platform\.OS === 'android'\s*\? await resolveDisplayedAndroidMessage\(notification\.id, message\)/,
    );
    assert.match(TRAY_EVENTS, /if \(!target\) return;/);
    assert.match(TRAY_EVENTS, /handleReply\(target, detail\.input \?\? ''\)/);
  });
});
